from pathlib import Path
r=Path('/workspace/thesis')
changes={}
def rep(name,a,b):
 p=r/name; raw=p.read_bytes(); x=a.encode();y=b.encode()
 if x not in raw:x=x.replace(b'\n',b'\r\n');y=y.replace(b'\n',b'\r\n')
 elif b'\n' not in x and b'\r\n' in raw:y=y.replace(b'\n',b'\r\n')
 assert raw.count(x)==1,(name,a[:90],raw.count(x));p.write_bytes(raw.replace(x,y));changes.setdefault(name,[]).append((a,b))
def add_after_label(name,label,text):rep(name,label+'\n\n',label+'\n\n'+text+'\n\n')

add_after_label('Chapters/07_Hardware/chapter.tex',r'\label{ch:hardware}',r'''The circuit contains a power path and a control path. The power path carries energy from the AC input to the load. The control path measures the circuit and sends low-voltage commands to the switching stage. A microcontroller (MCU), the programmable control chip, connects to those signals through its electrical terminals, called pins. Pin labels and their roles are introduced in \cref{sec:intro-controller-basics}. Here, the signal function is stated alongside the label so the circuit connections can be followed.''')
add_after_label('Chapters/07_Hardware/04_GaN_Half_Bridge.tex',r'\label{sec:hw-halfbridge}',r'''A half bridge contains two electronic switches connected between the positive DC link and its return. Their junction is the switch node. Each switch is a field-effect transistor (FET), whose control terminal is called the gate. The driver converts the microcontroller's low-voltage command into the gate drive needed by the transistor. The MCU pins therefore carry control signals, not the converter's load current.''')
rep('Chapters/07_Hardware/04_GaN_Half_Bridge.tex','VSW also couples through capacitance','The half-bridge switch node, labeled VSW, also couples through capacitance')
rep('Chapters/07_Hardware/05_Gate_Drive.tex',r'''Logic commands are sent from the STM32 to the integrated driver. PA8 and PA9 carry the fixed \SI{1}{\mega\hertz} carrier. PA10 controls EN to enable groups of switching cycles and adjust energy transfer. Center-aligned TIM1 operation places the programmed dead interval at both transitions.''',r'''Logic commands are low-voltage signals sent from the STM32 controller to the integrated driver. On the G071 test platform, the two carrier-command outputs, PA8 and PA9, carry the fixed \SI{1}{\mega\hertz} pulse pattern. A separate enable output, PA10, drives the driver's EN input to permit or inhibit groups of switching cycles. This adjusts energy transfer without changing the carrier frequency. TIM1 is the internal hardware timer used to generate the carrier. Its center-aligned counter runs up and down; the output timing provides the programmed dead interval at both transitions. Dead time is the gap intended to keep both power switches off while the command changes between them.''')
rep('Chapters/07_Hardware/07_USBC_Interface.tex','using PA1 feedback.','using the secondary-voltage feedback signal received at MCU input PA1.')
rep('Chapters/07_Hardware/08_Sensing.tex','The three analog signals pass through TLV9064 buffers before reaching the tested controller. PA0 indicates primary high voltage, PA1 indicates isolated secondary-bulk voltage, and PA2 carries the LMG2652 half-bridge-current signal. The AMC0330 transfers bulk-voltage information across the isolation barrier to the primary-side STM32.',r'''The controller measures three analog signals, meaning voltages that vary with the physical quantities being sensed. They pass through TLV9064 buffer circuits before reaching the tested controller; the buffers reduce the effect of MCU input loading on the sensing circuits. The scaled primary-voltage signal enters input PA0, the isolated secondary-bulk-voltage signal enters PA1, and a voltage representing LMG2652 half-bridge current enters PA2. These are sensing inputs, not connections that carry the load current or the full bulk voltage. The AMC0330 transfers the secondary-voltage information across the isolation barrier to the primary-side STM32.''')
rep('Chapters/07_Hardware/08_Sensing.tex','Correctly identifying the PA2 signal','Correctly identifying the half-bridge-current signal at PA2')
rep('Chapters/07_Hardware/08_Sensing.tex','Primary current cannot be multiplied by PA1','Primary current cannot be multiplied by the secondary-voltage reading from PA1')
rep('Chapters/07_Hardware/09_Protection.tex','bounded PA10 commands','bounded burst-enable commands on the G071 output PA10')
rep('Chapters/07_Hardware/09_Protection.tex','The PA2 current trip','The firmware current trip based on the PA2 sensing input')
rep('Chapters/07_Hardware/10_Auxiliary_Power.tex','The local rails, UART, inhibited PA10 state, carrier outputs, and analog feedback','The local supply rails, UART communication, inhibited burst-enable output PA10, carrier outputs, and analog feedback')
rep('Chapters/07_Hardware/10_Auxiliary_Power.tex','a valid PA1 voltage reading','a valid secondary-voltage reading from input PA1')
rep('Chapters/07_Hardware/12_EMI.tex','while PA10 adds the slower burst envelope.','while the G071 enable output PA10 adds the slower burst envelope.')

rep('Chapters/07_Hardware/16_V2_F410.tex','The MCU sheet 4 connections in \\Cref{tab:hw-v2-pinmap} require a different carrier assignment. The pair is driven by TIM1 CH1 and complementary CH1N. The low command was moved to PB13, leaving PA9 for USART1 TX. Enable was moved from PA10 to PA11, leaving PA10 for USART1 RX. This assignment allows the gate commands and UART to operate on the same MCU.',r'''The controller connections in MCU sheet 4 are summarized in \Cref{tab:hw-v2-pinmap}. A timer channel is one output path controlled by a hardware timer. Here, TIM1 channel CH1 and its complementary partner CH1N produce the paired carrier commands; the N identifies the complementary output, not another MCU pin number. The low-side command was moved to PB13, leaving PA9 for serial transmission through USART1 TX. The burst-enable output was moved from PA10 to PA11, leaving PA10 for serial reception through USART1 RX. TX and RX mean transmit and receive. USART1 is the MCU's serial-communication hardware, used here as a UART. The same label therefore has to be read with the board version: PA10 is enable on the G071 but serial receive on the F410. The table distinguishes these logical signal names from the physical package-pin numbers.''')
rep('Chapters/07_Hardware/16_V2_F410.tex','The following timing settings are those in the archived PWR-2.0.1 source.','The following timing settings are those in the archived PWR-2.0.1 source. Timer settings are stored in hardware control locations called registers. ARR sets the counter limit, CCR1 sets the channel compare threshold that determines output transitions, and DTG programs the gap between complementary commands. These names refer to timer settings, not electrical pins.')
rep('Chapters/07_Hardware/16_V2_F410.tex','ADC1 scans PA0, PA1, and PA2 continuously through DMA2 Stream0 Channel0, independently of the carrier.',r'''ADC1 is the internal analog-to-digital converter that turns each input voltage into a numerical reading. It scans the scaled primary-voltage input PA0, secondary-bulk-voltage input PA1, and half-bridge-current input PA2 continuously. Direct memory access (DMA) copies the results into memory without requiring the processor to move each reading. On the F410, DMA2 Stream0 Channel0 identifies the internal transfer route; it is separate from the ADC input-channel numbers in the pin table. Acquisition runs independently of the carrier.''')
rep('Chapters/07_Hardware/16_V2_F410.tex','PA1 remains the secondary-bulk voltage feedback. PA2 remains the primary half-bridge-current signal','The reading at PA1 remains the secondary-bulk voltage feedback. The reading at PA2 remains the primary half-bridge-current signal')
rep('Chapters/07_Hardware/17_V3_Edge_Card_Plan.tex','Primary\nand isolated secondary connections must remain distinct. PA1 remains\nsecondary-bulk feedback and PA2 remains a primary half-bridge-current\nsignal.','Primary\nand isolated secondary connections must remain distinct. The secondary-\nbulk feedback input remains PA1, and the primary half-bridge-current\nsensing input remains PA2.')

add_after_label('Chapters/08_Control_Firmware/chapter.tex',r'\label{ch:control}',r'''Firmware is the program run by the microcontroller (MCU). It reads the sensing inputs, decides how much switching is needed, and commands the driver through output pins. The labels PA0, PA1, and PA2 identify the sensing connections for primary voltage, secondary-bulk voltage, and primary half-bridge current. On the G071, PA8 and PA9 carry the switching commands and PA10 enables their bursts. These names identify MCU connections; they are not measured voltages or currents by themselves. The basic pin naming and signal paths are introduced in \cref{sec:intro-controller-basics}.''')
rep('Chapters/08_Control_Firmware/01_Control_Objectives.tex',r'''In PWR-1.9.20, the secondary-bulk voltage \(V_{\mathrm{sb}}\) is controlled from PA1. The MPQ4242 sets connector VBUS downstream. PA0 can limit duty through primary-voltage feed-forward, while PA2 is used for load classification and optional current protection. PA2 carries the primary half-bridge-current signal and cannot serve as direct USB-C output-current feedback.''',r'''In PWR-1.9.20, the secondary-bulk voltage \(V_{\mathrm{sb}}\) is regulated using its sensing input, PA1. The MPQ4242 sets connector VBUS downstream. The primary-voltage reading at PA0 can limit duty through feed-forward: the allowed command is reduced as the sensed primary voltage rises. The half-bridge-current reading at PA2 is used to classify loaded and unloaded operation and, when enabled, apply current protection. It is a primary-side signal and cannot serve as direct USB-C output-current feedback.''')
rep('Chapters/08_Control_Firmware/01_Control_Objectives.tex',r'Energy transfer is controlled through the average PA10 enable duty \(d_{\mathrm{EN}}\). PA8 and PA9 carry the fixed',r'Energy transfer is controlled through the average duty of the G071 burst-enable output PA10, \(d_{\mathrm{EN}}\). Duty is the fraction of an enable period during which switching is permitted. The two carrier-command outputs PA8 and PA9 carry the fixed')
rep('Chapters/08_Control_Firmware/02_Architecture_Timing.tex','The Arduino STM32 environment was used with direct peripheral configuration on the STM32G071. TIM1 was configured for center-aligned PA8/PA9 carrier commands','The Arduino STM32 software framework was used with direct configuration of the STM32G071 peripherals. A peripheral is a hardware block inside the MCU, such as a timer, converter, or serial interface. Timer TIM1 was configured to generate the paired carrier commands on outputs PA8/PA9 using center-aligned counting')
rep('Chapters/08_Control_Firmware/02_Architecture_Timing.tex','TIM3 schedules the slower PA10 envelope. Burst transitions are timed by bounded polling of TIM1 updates.','A second hardware timer, TIM3, schedules the slower burst-enable envelope on output PA10. The software checks for TIM1 counter-update events for a limited interval before changing enable. This is the bounded polling used to align burst transitions with the carrier.')
rep('Chapters/08_Control_Firmware/02_Architecture_Timing.tex','An allowed static \\SI{100}{\\percent} command holds PA10 high without repeated short gaps.',r'An allowed static \SI{100}{\percent} command holds the enable output PA10 at logic high, the voltage state that permits switching, without repeated short gaps. Logic low inhibits switching; it does not mean that the power-circuit capacitors have discharged.')
rep('Chapters/08_Control_Firmware/02_Architecture_Timing.tex','ADC acquisition runs independently of the foreground control loop. ADC1 scans PA0, PA1, and PA2 into a circular DMA buffer.',r'''Analog-to-digital converter (ADC) acquisition runs independently of the foreground control loop, the processor's repeated sequence of sensing and control decisions. ADC1 samples the primary-voltage input PA0, secondary-voltage input PA1, and current-related input PA2 in sequence. DMA transfers these readings into a circular buffer, a memory area reused from its beginning when the end is reached. General-purpose input/output (GPIO) refers to the digital pin hardware used to drive an output such as enable. The universal asynchronous receiver-transmitter (UART) is the serial interface used for commands and status messages.''')
rep('Chapters/08_Control_Firmware/03_Feedback_Calibration.tex',r'Each control decision depends on the measured signal and the conversion used to scale it. For a 12-bit count \(N_i\), pin voltage is calculated in the firmware:',r'Each control decision depends on the measured signal and the conversion used to scale it. The ADC returns an integer reading, called a count, that represents the input voltage relative to its reference voltage. The reference sets the conversion scale. For a 12-bit count \(N_i\), the low-voltage signal at the MCU input pin is calculated in the firmware:')
rep('Chapters/08_Control_Firmware/03_Feedback_Calibration.tex','The divider and isolation-amplifier conversion is then applied, followed by gain and offset. For PA1 this is','The measured MCU input voltage is then converted back to the physical circuit voltage using the resistor-divider and isolation-amplifier scale, followed by gain and offset corrections. For the secondary-bulk sensing input PA1 this is')
rep('Chapters/08_Control_Firmware/03_Feedback_Calibration.tex','A new PA1 sample','A new secondary-voltage sample from PA1')
rep('Chapters/08_Control_Firmware/04_V0_Open_Loop.tex','Open-loop commands were first used','In open-loop operation, the switching command is applied without automatically correcting it from the measured output voltage. These commands were first used')
rep('Chapters/08_Control_Firmware/08_Control_Law.tex','At light or no load, duty follows a hysteretic high/low state.','At light or no load, duty follows a hysteretic high/low state: different voltage thresholds are used to increase and reduce transfer, so a small change near one threshold does not repeatedly reverse the decision. High and low duty describe the amount of permitted switching, rather than the voltage state of a sensing pin.')
rep('Chapters/08_Control_Firmware/08_Control_Law.tex','When fresh or filtered PA1 reaches','When the fresh or filtered secondary-voltage reading from PA1 reaches')
rep('Chapters/08_Control_Firmware/08_Control_Law.tex','Loaded operation is identified using a PA2 threshold','Loaded operation is identified using a threshold on the primary-current reading from PA2')
rep('Chapters/08_Control_Firmware/08_Control_Law.tex','PA0 therefore limits the high command, while PA1 determines the voltage state and error.','The primary-voltage reading from PA0 therefore limits the high command, while the secondary-voltage reading from PA1 determines the voltage state and error.')
rep('Chapters/08_Control_Firmware/09_Limits_Antiwindup.tex','PA10 has an envelope frequency','The G071 burst-enable output PA10 is scheduled with an envelope frequency')
rep('Chapters/08_Control_Firmware/10_Open_Circuit_Safety.tex','The no-load guard uses PA2','The no-load guard uses the primary-current indication at PA2')
