notes=Path('/workspace/tooling/mcu-reader-introduction/hardware-firmware-notes.md')
lines=['# Hardware and firmware reader introduction','',f'Edited {len(changes)} files with {sum(map(len,changes.values()))} targeted prose additions/replacements. No firmware, settings, pin assignment, equation, source figure, or table row was changed. Original line endings retained through byte-based replacements.','', 'Main changes:','- Defined the control path, MCU pins, and driver-versus-load-current distinction before hardware pin references.','- Introduced gate commands and enable by physical role before identifiers.','- Explained ADC readings, buffering and scaling, hardware timers/channels/registers, DMA routes, GPIO and UART.','- Made the G071 PA10 enable versus F410 PA10 UART receive assignment explicit.','- Replaced ambiguous expressions such as “PA1 regulates” in running prose with the reading or signal derived from the pin. Existing figures and table entries remain unchanged.','', 'Changed files:']
